action.command:
cat > /tmp/drift2.php <<'EOF'
<?php
$storage = new \Drupal\Core\Config\FileStorage(\Drupal::root() . '/../config/sync');
$sync = $storage->listAll();
$active = \Drupal::configFactory()->listAll();
foreach (array_intersect($sync,$active) as $n) {
  $a = \Drupal::config($n)->getRawData();
  $s = $storage->read($n);
  unset($a['uuid'],$a['_core'],$s['uuid'],$s['_core']);
  if ($a != $s) echo "$n\n";
}
echo "=== only in db ===\n";
foreach (array_diff($active,$sync) as $n) echo "$n\n";
EOF
cd /workspace && cp /tmp/drift2.php /workspace/drift2_tmp.php && su ddevuser -c "ddev drush php:script drift2_tmp.php" 2>&1 | tail -160; rm -f /workspace/drift2_tmp.php

